import json,html,collections
from pathlib import Path
P=Path(__file__).resolve().parent;d=json.loads((P/'audit.json').read_text(encoding='utf-8'));v=json.loads((P/'acceptance_results.json').read_text(encoding='utf-8'))
E=lambda x:html.escape(str(x if x is not None else ''))
F=d['findings'];C=d['counts'];sources=d['sources']
rows=[]
priority=[
 ('Government sukuk income','GL_CATEGORY',lambda f:f['ehab_cells']=='K162','Ehab GL 4004020004 maps to PL category 65073 in both GL versions. Systems uses 65037.'),
 ('Bond profit expense','GL_CATEGORY',lambda f:f['ehab_cells']=='K248','Ehab’s 5501 GL prefix maps to 66560–66562. Systems uses 60031–60034.'),
 ('Subsidiary finance companies','GL_CATEGORY',lambda f:f['ehab_cells']=='K938','Systems omits 11903–11907 and adds 11908 relative to Ehab’s selected GLs.'),
 ('Investment property','GL_CATEGORY',lambda f:f['ehab_cells']=='K976','Ehab GL 1700000001 maps to 13337. Systems Table 15 uses 11320.'),
 ('Intangible assets','GL_CATEGORY',lambda f:f['ehab_cells']=='K1042','The “Other” intangible line omits 11301 and 11570 and includes 11550 relative to the selected GLs.'),
 ('Bank profit expense','GL_CATEGORY',lambda f:f['ehab_cells']=='K256','Systems includes product category 15154 in a P&L selector and omits 66586–66588 from the selected GL population.'),
 ('Treasury-share duplicate','EHAB_DUPLICATE',lambda f:True,'Ehab K109 and K111 both use GL 3200000001. Current GL maps it to 18008. Systems distinguishes 18008 nominal and 18006 premium/discount.'),
 ('Credit-quality calculations','CREDIT_QUALITY_FORMULA',lambda f:True,'75 formulas use the wrong direct/indirect or performing/non-performing components. The source also contains 90 saved #VALUE! cells.'),
 ('Maturity calculations','MATURITY_DIRECTION',lambda f:True,'Tables 10 and 24 subtract maturity from system date for future bands. Table 10 also omits eight exact boundaries and tests “Without Maturity” as ≤1 day.'),
 ('Column totals','TOTAL_COLUMNS',lambda f:True,'25 written total expressions use the wrong labelled columns, including ASSET - 100, Table 9 and Table 26.'),
 ('Guarantees and missing balance codes','ABSENT_BALANCE_TYPE',lambda f:'CONTDRBL' in f['title'],'CONTDRBL is written in the source but absent from the supplied ECB. CONTDBBL exists. The source code must be confirmed before substitution.'),
 ('Accrued and deferred profit','CROSS_SCHEDULE_OVERLAP',lambda f:True,'TABLE 19 accrued income and Table 30 deferred liability both select ACCDEFERREDPFT in categories 3000–3999. The complete accounting treatment needs reconciliation.'),
 ('Changed clearing-account mapping','GL_CATEGORY',lambda f:f['ehab_cells']=='L380','Table 2 matches the September GL category set. The current GL adds 18062, so this is a later-version difference.'),
 ('Missing original schedules','MISSING_SCHEDULE',lambda f:True,'BO Tables 020 and 038 have no worksheet in the supplied Systems mapping. Their original mapping cannot be certified from this file.')]
for title,typ,pred,text in priority:
 match=next((f for f in F if f['type']==typ and pred(f)),None)
 if match:rows.append({'title':title,'text':text,'id':match['id'],'status':match['status']})
data={'counts':C,'findings':F,'comparisons':d['comparisons'],'priorities':rows,'validation':v,'sources':[{k:m[k] for k in ['label','filename','sha256','sheets','cells']} for m in sources]}
payload=json.dumps(data,ensure_ascii=False).replace('</','<\/')
template=r'''<!doctype html><html lang="en"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>NBS mapping cell audit — 21 October 2026</title>
<style>:root{font-family:Arial,sans-serif;color:#20384b;background:#f2f5f8}*{box-sizing:border-box}body{margin:0}header{padding:30px max(24px,calc((100vw - 1280px)/2));background:#15324c;color:white}h1{font-size:28px;line-height:1.25;margin:0 0 12px}header p{color:#dce6ee;max-width:1050px;line-height:1.6;margin:8px 0}header a{color:white}nav{position:sticky;top:0;z-index:5;background:white;border-bottom:1px solid #cbd6de;padding:12px 24px;display:flex;gap:12px;flex-wrap:wrap}button,select,input{font:inherit;padding:10px 14px;border-radius:5px;border:1px solid #acbdca;background:white;color:#20384b}button{cursor:pointer}button.active,button.primary{background:#15324c;color:white}main{max-width:1330px;padding:24px;margin:auto}.panel{display:none}.panel.active{display:block}h2{font-size:22px}h3{font-size:17px}p{line-height:1.6}.counts{display:flex;gap:10px;flex-wrap:wrap;margin:0 0 24px}.count{padding:16px;background:white;border:1px solid #d9e2e8;min-width:175px}.count b{font-size:25px;display:block;margin-bottom:6px}.grid{display:grid;grid-template-columns:repeat(auto-fit,minmax(350px,1fr));gap:14px}.topic{background:white;padding:20px;border-left:4px solid #466983}.topic h3{margin-top:0}.topic p{font-size:15px}.pill{display:inline-block;padding:4px 7px;border-radius:3px;background:#e9eef2;font-size:12px;font-weight:bold}.CONFIRMED{background:#fce4e4;color:#88252a}.DIFFERENCE{background:#fff1d6;color:#78510d}.GAP{background:#f2eafa;color:#624276}.controls{display:flex;gap:8px;flex-wrap:wrap;position:sticky;top:69px;background:#f2f5f8;padding:12px 0;z-index:3}.controls input{min-width:260px;flex:1}details{background:white;border:1px solid #d9e2e8;border-radius:5px;margin:10px 0}summary{cursor:pointer;padding:16px;display:flex;align-items:start;gap:12px;line-height:1.5}summary b{min-width:90px}summary .name{flex:1}.body{padding:0 20px 20px 122px}.body h4{margin:15px 0 5px;font-size:14px}.body p,.body pre{margin:4px 0 14px;font:14px/1.6 Arial,sans-serif;white-space:pre-wrap;overflow-wrap:anywhere}.body .source{padding:12px;background:#f4f7f9}a{color:#145b86}.note{background:#fff4dd;padding:16px;border-left:4px solid #bb8b2d}.subtle{color:#577084;font-size:14px}.scroller{overflow:auto;background:white}table{border-collapse:collapse;font-size:14px;width:100%}th{background:#15324c;color:white;text-align:left}td,th{padding:12px;vertical-align:top;border-bottom:1px solid #dbe4eb}td{white-space:pre-wrap;min-width:130px;max-width:550px;overflow-wrap:anywhere}td.wide{min-width:300px}pre.hash{font-size:12px;white-space:pre-wrap;overflow-wrap:anywhere}.end{padding:30px 0;font-size:14px;color:#577084}@media(max-width:700px){.body{padding:0 14px 14px}summary{flex-wrap:wrap}.controls{position:static}.grid{grid-template-columns:1fr}}@media print{nav,.controls,button{display:none}.panel{display:block!important}details{break-inside:avoid}details .body{display:block}header{background:white;color:black}header p{color:black}main{max-width:none}.grid{display:block}.topic{break-inside:avoid}}</style>
<header><h1>NBS mapping: Ehab, Systems and GL</h1><p>Cell audit dated 21 October 2026. The supplied 6 October Systems workbook is compared with Ehab’s mapping and both the 9 September and current GL mappings.</p><p><a href="NBS_Ehab_Systems_GL_Cell_Audit_21Oct2026.xlsx">Open the complete Excel review</a> · <a href="All_findings.csv">Every numbered finding</a> · <a href="GL_sixth_segment_trace.csv">Full GL trace</a></p></header>
<nav><button class="active" data-panel="main">Main findings</button><button data-panel="findings">Every finding</button><button data-panel="comparison">GL comparison</button><button data-panel="method">Scope and checks</button></nav><main>
<section id="main" class="panel active"><div class="counts" id="counts"></div><p class="note">Counts refer to finding occurrences. A copied condition in another cell appears separately; one cell can have several findings. Differences and missing inputs are not automatically proven errors.</p><h2>Findings to resolve first</h2><div class="grid" id="priority"></div><p class="end">The original workbooks and production engine are preserved. Yellow decision fields in the Excel review let stakeholders record the agreed treatment.</p></section>
<section id="findings" class="panel"><h2>Every finding, one by one</h2><div class="controls"><input id="q" placeholder="Search category, GL, cell, issue or text" aria-label="Search findings"><select id="status" aria-label="Status"><option value="">All statuses</option></select><select id="kind" aria-label="Finding type"><option value="">All finding types</option></select><select id="sheet" aria-label="Worksheet"><option value="">All worksheets</option></select><button id="export">Save filtered CSV</button></div><p id="number" class="subtle"></p><div id="list"></div></section>
<section id="comparison" class="panel"><h2>GL sixth segment to Systems category</h2><p>These comparisons use Ehab’s explicit GL selectors and exact recorded hierarchy links. A matching category set does not validate sector, currency, product, balance type, sign or source completeness.</p><input id="cq" placeholder="Search Ehab cell, category or schedule" aria-label="Search category comparison"><p id="cn" class="subtle"></p><div class="scroller"><table><thead><tr><th>Ehab / schedule</th><th>Line / original rule</th><th>Systems reference / categories</th><th>Missing against current</th><th>Additional against current</th><th>9 September comparison</th><th>Result / limitations</th></tr></thead><tbody id="ct"></tbody></table></div></section>
<section id="method" class="panel"><h2>Scope and evidence</h2><p>Every populated cell was captured from every supplied worksheet, including notes, helper cells, formulas and cached errors. Styled empty cells are counted in Source coverage. Rule-based checks cover explicit criteria, dictionary consistency, currency-column differences, formulas, maturity boundaries, absent balance types and exact GL segment bridges. An unflagged cell is not a certificate of semantic correctness.</p><p>The GL sixth segment is matched as text. The trace retains each source row, category or Migration PL category, sector, department, product, residence, balance type and the signed Ehab leg. The current v6 change to GL Mapping!L48311 is recorded separately from its immutable base workbook. Unsupported expressions, treasury data and missing lookup definitions remain visible as unverified.</p><p>Reporting basis: 30 September 2026. Original October category-entry dates remain unchanged under the owner-confirmed source-specific September policy. This review does not claim a same-date monetary impact or a fully reconciled NBS.</p><div id="sourcecards"></div><h2 id="checktitle"></h2><div class="scroller"><table><thead><tr><th>Acceptance check</th><th>Result</th></tr></thead><tbody id="checks"></tbody></table></div><p><a href="NBS_cell_scan.csv">Every populated NBS cell</a> · <a href="Referenced_GL_rows.csv">All referenced GL rows</a> · <a href="Source_sheet_coverage.csv">Every source worksheet</a></p></section>
</main><script>const D=__PAYLOAD__;const $=s=>document.querySelector(s);const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));const pill=s=>`<span class="pill ${s==='INPUT GAP'?'GAP':esc(s)}">${esc(s)}</span>`;function activate(id){document.querySelectorAll('.panel').forEach(x=>x.classList.toggle('active',x.id===id));document.querySelectorAll('nav button').forEach(x=>x.classList.toggle('active',x.dataset.panel===id))}document.querySelectorAll('nav button').forEach(x=>x.onclick=()=>activate(x.dataset.panel));
$('#counts').innerHTML=[[D.counts.nbs_populated_cells,'NBS source cells'],[D.counts.findings,'Finding occurrences'],[D.counts.comparisons,'GL row comparisons'],[D.validation.passed,'Acceptance checks passed']].map(([n,t])=>`<div class="count"><b>${n.toLocaleString()}</b>${t}</div>`).join('');
$('#priority').innerHTML=D.priorities.map(p=>`<article class="topic"><h3>${esc(p.title)}</h3>${pill(p.status)}<p>${esc(p.text)}</p><a href="#${p.id}" data-id="${p.id}">Inspect ${p.id}</a></article>`).join('');
function options(sel,arr){$(sel).innerHTML+=Array.from(new Set(arr)).sort().map(x=>`<option value="${esc(x)}">${esc(x)}</option>`).join('')};options('#status',D.findings.map(f=>f.status));options('#kind',D.findings.map(f=>f.type));options('#sheet',D.findings.map(f=>f.systems_sheet||'Ehab / coverage'));
let filtered=D.findings;function draw(){const q=$('#q').value.toLowerCase(),st=$('#status').value,k=$('#kind').value,sh=$('#sheet').value;filtered=D.findings.filter(f=>(!q||JSON.stringify(f).toLowerCase().includes(q))&&(!st||f.status===st)&&(!k||f.type===k)&&(!sh||(f.systems_sheet||'Ehab / coverage')===sh));$('#number').textContent=`${filtered.length.toLocaleString()} of ${D.findings.length.toLocaleString()} finding occurrences`;
$('#list').innerHTML=filtered.map(f=>`<details id="${f.id}"><summary><b>${f.id}</b>${pill(f.status)}<span class="name">${esc(f.title)}<br><span class="subtle">${esc(f.systems_sheet)} ${esc(f.systems_cells)}${f.ehab_cells?' · Ehab '+esc(f.ehab_cells):''}</span></span></summary><div class="body"><h4>Evidence</h4><pre class="source">${esc(f.detail)}</pre>${f.gl_cells?'<h4>GL references</h4><pre>'+esc(f.gl_cells)+'</pre>':''}${f.missing_categories?'<h4>Missing from Systems, relative to the selected current GLs</h4><pre>'+esc(f.missing_categories)+'</pre>':''}${f.extra_categories?'<h4>Additional in Systems, relative to the selected current GLs</h4><pre>'+esc(f.extra_categories)+'</pre>':''}${f.baseline_9sep?'<h4>9 September version</h4><pre>'+esc(f.baseline_9sep)+'</pre>':''}<h4>Proposed handling</h4><p>${esc(f.action)}</p>${f.other_evidence?'<h4>Other original evidence</h4><pre>'+esc(f.other_evidence)+'</pre>':''}${f.limits?'<h4>What remains uncertain</h4><p>'+esc(f.limits)+'</p>':''}</div></details>`).join('')}
['#q','#status','#kind','#sheet'].forEach(s=>$(s).addEventListener('input',draw));draw();
function jump(id){activate('findings');$('#q').value=id;$('#status').value='';$('#kind').value='';$('#sheet').value='';draw();const el=document.getElementById(id);if(el){el.open=true;el.scrollIntoView({block:'start'})}}document.querySelectorAll('[data-id]').forEach(a=>a.onclick=e=>{e.preventDefault();history.replaceState(null,'','#'+a.dataset.id);jump(a.dataset.id)});
$('#export').onclick=()=>{const heads=['id','status','table','title','systems_sheet','systems_cells','ehab_cells','gl_cells','detail','missing_categories','extra_categories','baseline_9sep','action','limits'];const quote=v=>'"'+String(v??'').replaceAll('"','""')+'"';const text='\ufeff'+[heads,...filtered.map(f=>heads.map(h=>f[h]))].map(r=>r.map(quote).join(',')).join('\r\n');const a=document.createElement('a');a.href=URL.createObjectURL(new Blob([text],{type:'text/csv;charset=utf-8'}));a.download='NBS_filtered_findings.csv';a.click();URL.revokeObjectURL(a.href)};
function comp(){const q=$('#cq').value.toLowerCase(),rows=D.comparisons.filter(x=>!q||JSON.stringify(x).toLowerCase().includes(q));$('#cn').textContent=`${rows.length} of ${D.comparisons.length} comparisons`;$('#ct').innerHTML=rows.map(x=>`<tr><td>${esc(x.ehab_cell)}<br>${esc(x.table)}</td><td class="wide"><b>${esc(x.description)}</b><br>${esc(x.ehab_rule)}</td><td class="wide">${esc(x.systems_reference)}<br>${esc(x.systems_categories||'No safe numeric category bridge')}<br><small>${esc(x.criterion_references||'')}</small></td><td>${esc(x.missing_current||'—')}</td><td>${esc(x.extra_current||'—')}</td><td>Missing: ${esc(x.missing_9sep||'—')}<br>Additional: ${esc(x.extra_9sep||'—')}</td><td class="wide"><b>${esc(x.status)}</b><br>${esc(x.note)}</td></tr>`).join('')}$('#cq').oninput=comp;comp();
$('#sourcecards').innerHTML=D.sources.map(s=>`<article class="topic"><h3>${esc(s.filename)}</h3><p>${s.sheets} worksheets · ${s.cells.toLocaleString()} populated cells</p><pre class="hash">SHA256 ${esc(s.sha256)}</pre></article>`).join('');$('#checktitle').textContent=`${D.validation.passed} acceptance checks passed; ${D.validation.failed} failed`;$('#checks').innerHTML=D.validation.checks.map(c=>`<tr><td>${esc(c.check)}</td><td>${esc(c.result)}</td></tr>`).join('');if(location.hash.startsWith('#NBS-'))jump(location.hash.slice(1));</script></html>'''
(P/'NBS_All_Mismatches_21Oct2026.html').write_text(template.replace('__PAYLOAD__',payload),encoding='utf-8')
md=['# NBS Ehab / Systems / GL cell audit','',f'{C["findings"]} finding occurrences. Copied occurrences are separate; one cell can have several findings. Status distinguishes confirmed defects from differences, ambiguity, input gaps and review topics.','',f'{C["nbs_populated_cells"]:,} populated NBS cells and {sum(m["cells"] for m in sources):,} total source cells captured across {sum(m["sheets"] for m in sources)} worksheets.','']
for f in F:
 md.extend([f'## {f["id"]} — {f["status"]} — {f["title"]}','',f'Systems: {f["systems_sheet"]}!{f["systems_cells"]} · Ehab: {f["ehab_cells"]} · GL: {f["gl_cells"]}','',f['detail'],'',f'Handling: {f["action"]}',f'Limits: {f["limits"]}',''])
(P/'All_findings_one_by_one.md').write_text('\n'.join(md),encoding='utf-8')
(P/'READ_ME_FIRST.txt').write_text(f'''Open NBS_All_Mismatches_21Oct2026.html in Edge or Chrome. It works offline without Python or installations.
Open NBS_Ehab_Systems_GL_Cell_Audit_21Oct2026.xlsx for stakeholder review. Yellow cells record a decision and owner; original mappings are not modified.

{C['nbs_populated_cells']:,} populated cells in Ehab and Systems were captured. The two GL originals were scanned across all their worksheets. Total source cells: {sum(m['cells'] for m in sources):,}.
{C['findings']:,} numbered finding occurrences are listed individually. Repeated copies and multiple issues in one cell are separate occurrences, not independent financial misstatements.
{v['passed']} acceptance checks passed. Referenced_GL_rows.csv contains all {C['gl_evidence_rows']:,} underlying selected GL rows; GL_sixth_segment_trace.csv preserves the grouped conditions for both versions.

The 9 September GL and current supplied GL plus logged v6 edit are kept separate. A later mapping change is not labelled as an original October mistake.
Category agreement does not prove a complete NBS rule. Residence, currency, sector, product, department, balance type, accounting sign and source completeness still matter.
No original source, production mapping, owner policy or engine was changed by this audit. No monetary impact or 100% reconciliation is claimed.
''',encoding='utf-8')
print(json.dumps({'html_bytes':(P/'NBS_All_Mismatches_21Oct2026.html').stat().st_size,'priority_topics':len(rows),'findings':len(F)}))
